const listFederationKeys = `-- name: ListFederationKeys :many

SELECT kid, public_key, public_jwk, wrapped_private_key, kek_id, state, created_at, created_by, rotated_at,
       (coalesce(rotated_at, now()) + make_interval(secs => $1::int))::timestamptz AS retires_at,
       (state = 'ACTIVE' OR rotated_at > now() - make_interval(secs => $1::int))::bool AS live
FROM pc.federation_keys
WHERE org_id = $2 AND state <> 'RETIRED'
ORDER BY created_at DESC, kid
`

type ListFederationKeysRow struct {
	Kid               string
	PublicKey         []byte
	PublicJwk         []byte
	WrappedPrivateKey []byte
	KekID             string
	State             string
	CreatedAt         time.Time
	CreatedBy         string
	RotatedAt         *time.Time
	RetiresAt         time.Time
	Live              bool
}

// SPDX-License-Identifier: BUSL-1.1
// Copyright (c) 2026 Joshua Kato. See LICENSE and NOTICE.
//
// Cross-org federation queries (G0 M35 D1020..D1024). Every query runs
// inside db.InTenantTx and also filters by org_id explicitly.
// An org's federation keys that are not RETIRED. live is false for a
// RETIRING key whose 7-day overlap has ended: it signs and verifies
// nothing, and the next change retires it.
func (q *Queries) ListFederationKeys(ctx context.Context, overlapSeconds int32, orgID ids.OrgID) ([]ListFederationKeysRow, error) {
	rows, err := q.db.Query(ctx, listFederationKeys, overlapSeconds, orgID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListFederationKeysRow{}
	for rows.Next() {
		var i ListFederationKeysRow
		if err := rows.Scan(
			&i.Kid,
			&i.PublicKey,
			&i.PublicJwk,
			&i.WrappedPrivateKey,
			&i.KekID,
			&i.State,
			&i.CreatedAt,
			&i.CreatedBy,
			&i.RotatedAt,
			&i.RetiresAt,
			&i.Live,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

